 static void Import(string name,int count,float height){string path=Dir+name+".png";var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Multiple;i.isReadable=true;i.alphaIsTransparency=true;i.maxTextureSize=8192;i.textureCompression=TextureImporterCompression.Uncompressed;i.mipmapEnabled=false;i.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var px=tex.GetPixels32();float w=(float)tex.width/count;var bottoms=new int[count];var tops=new int[count];for(int k=0;k<count;k++){bottoms[k]=tex.height;for(int y=0;y<tex.height;y++)for(int x=(int)(k*w);x<(int)((k+1)*w);x++)if(px[y*tex.width+x].a>80){bottoms[k]=Mathf.Min(bottoms[k],y);tops[k]=Mathf.Max(tops[k],y);}}float ppu=Enumerable.Range(0,count).Select(k=>tops[k]-bottoms[k]+1).Max()/height;i.spritePixelsPerUnit=ppu;
