 static void BuildMap(int index){string path=Dir+"map/"+Names[index]+".tmx";var xml=XDocument.Load(path).Root;int width=(int)F(xml,"width"),height=(int)F(xml,"height");float offset=index*100;var root=rooms[index]=new GameObject(Names[index]);root.transform.position=new Vector3(offset,0);bounds[index]=new Rect(offset,0,width*8/PPU,height*8/PPU);points[index]=new Dictionary<string,Vector3>();var tiles=new List<Tiles>();foreach(var e in xml.Elements("tileset")){string tsPath=Dir+"map/"+e.Attribute("source").Value;var ts=XDocument.Load(tsPath).Root;string image=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(tsPath),ts.Element("image").Attribute("source").Value));image="Assets/"+image.Split(new[]{"/Assets/"},StringSplitOptions.None).Last();var imp=(TextureImporter)AssetImporter.GetAtPath(image);imp.textureType=TextureImporterType.Default;imp.npotScale=TextureImporterNPOTScale.None;imp.alphaIsTransparency=true;imp.mipmapEnabled=false;imp.filterMode=FilterMode.Point;imp.wrapMode=TextureWrapMode.Clamp;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.maxTextureSize=8192;imp.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(image);string matPath=Dir+"Generated/"+Path.GetFileNameWithoutExtension(tsPath)+".mat";var mat=new Material(Shader.Find("DimensionShifter/HollowMap")){mainTexture=tex};Save(mat,matPath);tiles.Add(new Tiles{first=(uint)F(e,"firstgid"),columns=(int)F(ts,"columns"),w=(int)F(ts,"tilewidth"),h=(int)F(ts,"tileheight"),tex=tex,mat=AssetDatabase.LoadAssetAtPath<Material>(matPath)});}
 int order=-35,foregroundOrder=10;foreach(var layer in xml.Elements("layer")){string name=layer.Attribute("name").Value;var data=layer.Element("data").Value.Split(new[]{',','\n','\r'},StringSplitOptions.RemoveEmptyEntries).Select(s=>uint.Parse(s.Trim())).ToArray();int layerOrder=name=="main"?0:name.StartsWith("foreground")?foregroundOrder++:order++;foreach(var tile in tiles){var vs=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();for(int n=0;n<data.Length;n++){uint gid=data[n]&0x0fffffff;if(gid==0)continue;var chosen=tiles.Last(t=>t.first<=gid);if(chosen!=tile)continue;int id=(int)(gid-tile.first),col=id%tile.columns,row=id/tile.columns;float x=(n%width)*8/PPU,y=(height-1-n/width)*8/PPU,z=0;int start=vs.Count;vs.AddRange(new[]{new Vector3(x,y,z),new Vector3(x+8/PPU,y,z),new Vector3(x+8/PPU,y+8/PPU,z),new Vector3(x,y+8/PPU,z)});var coords=new[]{new Vector2(0,1),new Vector2(1,1),new Vector2(1,0),new Vector2(0,0)};foreach(var c0 in coords){var c=c0;if((data[n]&0x80000000)!=0)c.x=1-c.x;if((data[n]&0x40000000)!=0)c.y=1-c.y;if((data[n]&0x20000000)!=0)c=new Vector2(c.y,c.x);uv.Add(new Vector2((col*tile.w+c.x*tile.w)/tile.tex.width,1-(row*tile.h+c.y*tile.h)/tile.tex.height));}tris.AddRange(new[]{start,start+1,start+2,start,start+2,start+3});}if(vs.Count==0)continue;var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(vs);mesh.SetUVs(0,uv);mesh.SetColors(Enumerable.Repeat(Color.white,vs.Count).ToArray());mesh.SetTriangles(tris,0);mesh.RecalculateBounds();string mp=Dir+"Generated/"+Names[index]+"_"+name+"_"+tile.first+".asset";Save(mesh,mp);var go=new GameObject(name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(mp);var mr=go.AddComponent<MeshRenderer>();mr.sharedMaterial=tile.mat;mr.sortingOrder=layerOrder;}}
 foreach(var obj in xml.Elements("objectgroup").Elements("object")){string name=(string)obj.Attribute("name")??"object";float x=F(obj,"x")/PPU,y=(height*8-F(obj,"y"))/PPU,w=F(obj,"width")/PPU,h=F(obj,"height")/PPU;var pos=new Vector3(offset+x,y);string key=name;while(points[index].ContainsKey(key))key+="_";if(name.StartsWith("door"))pos.y-=h;points[index][key]=pos;if(name!="platform"&&name!="wall"&&name!="ceiling"&&name!="spikes")continue;var go=new GameObject(name);go.transform.SetParent(root.transform,false);go.transform.localPosition=new Vector3(x,y);go.layer=8;var polygon=obj.Element("polygon");if(polygon!=null){var col=go.AddComponent<PolygonCollider2D>();col.points=polygon.Attribute("points").Value.Split(' ').Select(t=>t.Split(',')).Select(v=>new Vector2(float.Parse(v[0],System.Globalization.CultureInfo.InvariantCulture)/PPU,-float.Parse(v[1],System.Globalization.CultureInfo.InvariantCulture)/PPU)).ToArray();}else if(w>0&&h>0){var col=go.AddComponent<BoxCollider2D>();col.size=new Vector2(w,h);col.offset=new Vector2(w/2,-h/2);}if(name=="spikes"){go.layer=9;go.AddComponent<HollowHazard>();}}
